const path = require("node:path");
const {
  createContractProgram,
  renderTypeAliases,
  writeOrCheckContract,
} = require("./contract-generation.cjs");

const sources = ["contracts.ts", "claim-contracts.ts"].map((file) =>
  path.resolve(__dirname, "../src/lib/order-tracking", file),
);
const target = path.resolve(__dirname, "../.mercur/order-tracking-contracts.d.ts");
const program = createContractProgram(sources);
const result =
  '// Generated by scripts/generate-order-tracking-contracts.cjs. Do not edit.\nimport type { OrderStatus } from "@medusajs/framework/utils";\n\n' +
  renderTypeAliases(program, sources) +
  "\n";

writeOrCheckContract(
  target,
  result,
  "Order tracking contracts are stale; run pnpm tracking:contracts:generate",
);
